-- Truth-table explorer: all six 2-input gates in one entity.
-- Set a=0/1 and b=0/1 at different times in the Ports tab
-- and watch how each output reacts.

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity gates is
  port (
    a      : in  std_logic;
    b      : in  std_logic;
    o_and  : out std_logic;
    o_or   : out std_logic;
    o_xor  : out std_logic;
    o_nand : out std_logic;
    o_nor  : out std_logic;
    o_xnor : out std_logic
  );
end entity gates;

architecture rtl of gates is
begin
  o_and  <= a and b;
  o_or   <= a or  b;
  o_xor  <= a xor b;
  o_nand <= a nand b;
  o_nor  <= a nor  b;
  o_xnor <= a xnor b;
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity mux21 is
  port (
    sel : in  std_logic;
    a   : in  std_logic;
    b   : in  std_logic;
    y   : out std_logic
  );
end entity mux21;

architecture rtl of mux21 is
begin
  y <= a when sel = '0' else b;
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity decoder38 is
  port (
    sel : in  std_logic_vector(2 downto 0);
    y   : out std_logic_vector(7 downto 0)
  );
end entity decoder38;

architecture rtl of decoder38 is
begin
  with sel select
    y <=
      "00000001" when "000",
      "00000010" when "001",
      "00000100" when "010",
      "00001000" when "011",
      "00010000" when "100",
      "00100000" when "101",
      "01000000" when "110",
      "10000000" when others;
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity adder4 is
  port (
    a    : in  std_logic_vector(3 downto 0);
    b    : in  std_logic_vector(3 downto 0);
    cin  : in  std_logic;
    sum  : out std_logic_vector(3 downto 0);
    cout : out std_logic
  );
end entity adder4;

architecture rtl of adder4 is
  signal t : unsigned(4 downto 0);
begin
  t    <= resize(unsigned(a), 5) + resize(unsigned(b), 5) + ("0000" & cin);
  sum  <= std_logic_vector(t(3 downto 0));
  cout <= t(4);
end architecture rtl;

-- BUG: this tristate buffer should output 'Z' (high impedance)
-- when oe='0'. Right now it drives the bus either way.
-- Fix the condition on the concurrent assignment.

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity tristate is
  port (
    oe : in  std_logic;
    d  : in  std_logic;
    y  : out std_logic
  );
end entity tristate;

architecture rtl of tristate is
begin
  -- Hint: the 'Z' branch fires when oe is low, not the other way around.
  y <= d when oe = '0' else 'Z';
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity dff is
  port (
    clk   : in  std_logic;
    reset : in  std_logic;
    d     : in  std_logic;
    q     : out std_logic
  );
end entity dff;

architecture rtl of dff is
begin
  process(clk, reset)
  begin
    if reset = '1' then
      q <= '0';
    elsif rising_edge(clk) then
      q <= d;
    end if;
  end process;
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity shift8 is
  port (
    clk   : in  std_logic;
    reset : in  std_logic;
    din   : in  std_logic;
    q     : out std_logic_vector(7 downto 0)
  );
end entity shift8;

architecture rtl of shift8 is
  signal r : std_logic_vector(7 downto 0) := (others => '0');
begin
  process(clk, reset)
  begin
    if reset = '1' then
      r <= (others => '0');
    elsif rising_edge(clk) then
      -- shift left, new bit comes in at the LSB
      r <= r(6 downto 0) & din;
    end if;
  end process;

  q <= r;
end architecture rtl;

-- BUG: this process forgets to assign y in one branch,
-- which causes the synthesizer to infer a latch.
-- Fix it so the behavior is purely combinational
-- (assign y on EVERY path through the process).

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

entity latch_bug is
  port (
    enable : in  std_logic;
    a      : in  std_logic;
    b      : in  std_logic;
    y      : out std_logic
  );
end entity latch_bug;

architecture rtl of latch_bug is
begin
  process(enable, a, b)
  begin
    if enable = '1' then
      y <= a and b;
    end if;
    -- Missing: what should y be when enable = '0'?
  end process;
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity traffic is
  port (
    clk    : in  std_logic;
    reset  : in  std_logic;
    red    : out std_logic;
    yellow : out std_logic;
    green  : out std_logic
  );
end entity traffic;

architecture rtl of traffic is
  type state_t is (S_RED, S_GREEN, S_YELLOW);
  signal state, next_state : state_t;
  signal count : unsigned(3 downto 0) := (others => '0');
  constant HOLD : unsigned(3 downto 0) := "0111";  -- 7 ticks per colour
begin

  -- state register
  process(clk, reset)
  begin
    if reset = '1' then
      state <= S_RED;
      count <= (others => '0');
    elsif rising_edge(clk) then
      if count = HOLD then
        state <= next_state;
        count <= (others => '0');
      else
        count <= count + 1;
      end if;
    end if;
  end process;

  -- next-state logic
  process(state)
  begin
    case state is
      when S_RED    => next_state <= S_GREEN;
      when S_GREEN  => next_state <= S_YELLOW;
      when S_YELLOW => next_state <= S_RED;
    end case;
  end process;

  -- Moore outputs: function of state only
  red    <= '1' when state = S_RED    else '0';
  green  <= '1' when state = S_GREEN  else '0';
  yellow <= '1' when state = S_YELLOW else '0';

end architecture rtl;

-- Project: vending machine
--
-- Your FSM must:
--   • accept two pulses: nickel (5¢) and dime (10¢)
--   • track the running total
--   • assert 'dispense' for exactly one clock cycle when total >= 25¢
--   • assert 'change' if total > 25¢ after the coin that triggered the sale
--   • return to the idle state after dispensing
--
-- Acceptance criteria:
--   nickel*5 (=25¢)   → dispense=1, change=0
--   dime*2 + nickel*1 → dispense=1, change=0
--   dime*3 (=30¢)     → dispense=1, change=1

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity vending is
  port (
    clk      : in  std_logic;
    reset    : in  std_logic;
    nickel   : in  std_logic;  -- 5-cent coin pulse
    dime     : in  std_logic;  -- 10-cent coin pulse
    dispense : out std_logic;
    change   : out std_logic
  );
end entity vending;

architecture rtl of vending is
  -- TODO(student): add a coin-total register and the dispense/change logic.
  signal total : unsigned(5 downto 0) := (others => '0');
begin
  -- starter: counts coins; does not yet dispense. That's your job.
  process(clk, reset)
  begin
    if reset = '1' then
      total <= (others => '0');
    elsif rising_edge(clk) then
      if    nickel = '1' then total <= total + 5;
      elsif dime   = '1' then total <= total + 10;
      end if;
    end if;
  end process;

  dispense <= '0';  -- TODO
  change   <= '0';  -- TODO
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity rom16x8 is
  port (
    clk  : in  std_logic;
    addr : in  std_logic_vector(3 downto 0);
    data : out std_logic_vector(7 downto 0)
  );
end entity rom16x8;

architecture rtl of rom16x8 is
  type rom_t is array(0 to 15) of std_logic_vector(7 downto 0);
  -- Example contents: first 16 squares (0,1,4,9,16,25,36,49,64,81,100,121,144,169,196,225)
  constant ROM : rom_t := (
    x"00", x"01", x"04", x"09", x"10", x"19", x"24", x"31",
    x"40", x"51", x"64", x"79", x"90", x"A9", x"C4", x"E1"
  );
begin
  process(clk)
  begin
    if rising_edge(clk) then
      data <= ROM(to_integer(unsigned(addr)));
    end if;
  end process;
end architecture rtl;

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity ram32x8 is
  port (
    clk  : in  std_logic;
    we   : in  std_logic;
    addr : in  std_logic_vector(4 downto 0);
    din  : in  std_logic_vector(7 downto 0);
    dout : out std_logic_vector(7 downto 0)
  );
end entity ram32x8;

architecture rtl of ram32x8 is
  type mem_t is array(0 to 31) of std_logic_vector(7 downto 0);
  signal mem : mem_t := (others => (others => '0'));
begin
  process(clk)
  begin
    if rising_edge(clk) then
      if we = '1' then
        mem(to_integer(unsigned(addr))) <= din;
        dout <= din;                                 -- write-first read
      else
        dout <= mem(to_integer(unsigned(addr)));
      end if;
    end if;
  end process;
end architecture rtl;

-- Project: 8-bit ALU
--
-- opcode (3 bits) chooses the operation:
--   000 = ADD    (y = a + b)
--   001 = SUB    (y = a - b)
--   010 = AND
--   011 = OR
--   100 = XOR
--   101 = SHL    (y = a shifted left by 1)
--   110 = SHR    (y = a shifted right by 1)
--   111 = PASS_A (y = a)
--
-- Flags:
--   zero  = '1' when y is all zeros
--   carry = add/sub carry-out; undefined for logic ops (drive '0')
--
-- TODO: fill in the case branches.

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity alu8 is
  port (
    op    : in  std_logic_vector(2 downto 0);
    a     : in  std_logic_vector(7 downto 0);
    b     : in  std_logic_vector(7 downto 0);
    y     : out std_logic_vector(7 downto 0);
    zero  : out std_logic;
    carry : out std_logic
  );
end entity alu8;

architecture rtl of alu8 is
  signal result : std_logic_vector(7 downto 0);
  signal cout   : std_logic;
begin
  process(op, a, b)
    variable ext : unsigned(8 downto 0);
  begin
    cout   <= '0';
    case op is
      when "000" =>  -- ADD
        ext    := resize(unsigned(a), 9) + resize(unsigned(b), 9);
        result <= std_logic_vector(ext(7 downto 0));
        cout   <= ext(8);
      when "001" =>  -- SUB
        ext    := resize(unsigned(a), 9) - resize(unsigned(b), 9);
        result <= std_logic_vector(ext(7 downto 0));
        cout   <= ext(8);
      -- TODO: AND / OR / XOR / SHL / SHR / PASS_A
      when others =>
        result <= (others => '0');
    end case;
  end process;

  y     <= result;
  zero  <= '1' when result = x"00" else '0';
  carry <= cout;
end architecture rtl;

-- Project: UART TX
--
-- Assumes a 50 MHz clock. Baud = 115200.
-- You need to:
--   (1) count clk cycles to generate the baud tick (≈ 434 cycles / bit)
--   (2) when 'send' is pulsed, latch 'data' and start the frame
--   (3) transmit: start(0), bit0..bit7 (LSB first), stop(1)
--   (4) raise 'busy' during the whole frame

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity uart_tx is
  port (
    clk   : in  std_logic;
    reset : in  std_logic;
    send  : in  std_logic;
    data  : in  std_logic_vector(7 downto 0);
    tx    : out std_logic;
    busy  : out std_logic
  );
end entity uart_tx;

architecture rtl of uart_tx is
  -- idle state holds tx high; the receiver detects start by the falling edge
  signal tx_reg : std_logic := '1';
begin
  -- TODO: implement the state machine + shift register.
  tx   <= tx_reg;
  busy <= '0';
end architecture rtl;

-- Project: single-cycle 8-bit CPU
--
-- ISA (4-bit opcode + 4-bit immediate):
--   0000 iiii  LOAD  R0, #imm       -- R0 <= imm
--   0001 iiii  ADD   R0, #imm       -- R0 <= R0 + imm
--   0010 aaaa  JUMP  addr           -- PC <= addr
--   1111 ----  HALT
--
-- Scaffold:
--   • PC + ROM fetch
--   • Decode + execute + writeback
--   • 'halted' output once HALT is hit
--
-- Fill in the case statement for decode/execute.

library IEEE;
use IEEE.STD_LOGIC_1164.ALL;
use IEEE.NUMERIC_STD.ALL;

entity cpu8 is
  port (
    clk    : in  std_logic;
    reset  : in  std_logic;
    r0_out : out std_logic_vector(7 downto 0);
    halted : out std_logic
  );
end entity cpu8;

architecture rtl of cpu8 is
  type rom_t is array(0 to 15) of std_logic_vector(7 downto 0);
  constant PROGRAM : rom_t := (
    x"03",  -- LOAD R0, #3
    x"14",  -- ADD  R0, #4        -> R0 = 7
    x"12",  -- ADD  R0, #2        -> R0 = 9
    x"F0",  -- HALT
    others => x"00"
  );
  signal pc     : unsigned(3 downto 0) := (others => '0');
  signal r0     : unsigned(7 downto 0) := (others => '0');
  signal halt   : std_logic            := '0';
  signal instr  : std_logic_vector(7 downto 0);
begin
  instr <= PROGRAM(to_integer(pc));

  process(clk, reset)
  begin
    if reset = '1' then
      pc   <= (others => '0');
      r0   <= (others => '0');
      halt <= '0';
    elsif rising_edge(clk) then
      if halt = '0' then
        case instr(7 downto 4) is
          when "0000" => r0 <= resize(unsigned(instr(3 downto 0)), 8); pc <= pc + 1;
          when "0001" => r0 <= r0 + resize(unsigned(instr(3 downto 0)), 8); pc <= pc + 1;
          when "0010" => pc <= unsigned(instr(3 downto 0));
          when "1111" => halt <= '1';
          when others => pc <= pc + 1;
        end case;
      end if;
    end if;
  end process;

  r0_out <= std_logic_vector(r0);
  halted <= halt;
end architecture rtl;
